//! The `.wscripti` interface format (PRD §9.1): a textual, human-readable,
//! diff-friendly subset of wscript syntax that dumps every registered
//! module / function / type / const *declaration*, with no bodies.
//!
//! Both halves live here on purpose. [`render`] writes a registry out and
//! [`load`] reads one back in, and the format only has one definition for
//! as long as they can see each other: while they sat in different crates
//! the emitter wrote const values into a comment and the loader invented a
//! zero, so an interface silently lost every value the host registered —
//! a script reading `MAX_PANES` folded 0 against the interface and 16
//! against the live registration. (ADR-0002 keeps the two registries
//! disjoint; what an interface *does* declare must still be the truth.)
//!
//! Types are lowered by the checker's own resolver
//! ([`crate::check::resolve`]), so an interface cannot declare a type no
//! script could write.
//!
//! Loaded functions get stub implementations that fault if a VM ever calls
//! them — interface registries are for checking, not running. Constants are
//! the exception: they carry their value, and folding one needs no host.

use std::collections::HashMap;
use std::fmt::Write;
use std::sync::Arc;

use wscript_core::bytecode::Const;
use wscript_core::defs::{
    DefId, DefKind, DefTable, EnumDef, FIRST_FREE_DEF, StructDef, VariantDef, VariantKind,
};
use wscript_core::diag::Diagnostic;
use wscript_core::host::{HostCallable, HostCtx, HostError};
use wscript_core::registry::{HostFnDecl, HostFnEntry, ModuleDef, Registry, positional_param_name};
use wscript_core::span::Span;
use wscript_core::types::{FnSig, Type};
use wscript_core::value::Value;

use crate::ast::*;
use crate::check::resolve::{self, TypeScope};

// ------------------------------------------------------------------ emit

/// Render every registered declaration as `.wscripti` text.
pub fn render(reg: &Registry) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by wscript {} — host interface declarations.\n\
         // Consumed by the LSP and `wscript check` (list this file in wscript.toml).\n\
         // Do not edit by hand.",
        env!("CARGO_PKG_VERSION")
    );

    // Ambient types first (they belong to no namespace; modules may list
    // them, but the declarations live at the top level).
    for (i, def) in reg.defs.defs.iter().enumerate() {
        if (i as u32) < FIRST_FREE_DEF {
            continue;
        }
        let id = DefId(i as u32);
        match def {
            DefKind::Struct(s) if s.host => {
                out.push('\n');
                if s.opaque {
                    let _ = writeln!(out, "#[opaque]\nstruct {} {{}}", s.name);
                } else {
                    let _ = writeln!(out, "struct {} {{", s.name);
                    for (fname, fty) in &s.fields {
                        let _ = writeln!(out, "    {fname}: {},", fty.display(&reg.defs));
                    }
                    let _ = writeln!(out, "}}");
                }
                render_methods(&mut out, reg, id, &s.name);
            }
            DefKind::Enum(e) if e.host => {
                out.push('\n');
                let _ = writeln!(out, "enum {} {{", e.name);
                for v in &e.variants {
                    match v.kind {
                        VariantKind::Unit => {
                            let _ = writeln!(out, "    {},", v.name);
                        }
                        VariantKind::Tuple => {
                            let tys: Vec<String> =
                                v.fields.iter().map(|(_, t)| t.display(&reg.defs)).collect();
                            let _ = writeln!(out, "    {}({}),", v.name, tys.join(", "));
                        }
                        VariantKind::Struct => {
                            let fields: Vec<String> = v
                                .fields
                                .iter()
                                .map(|(n, t)| format!("{n}: {}", t.display(&reg.defs)))
                                .collect();
                            let _ = writeln!(out, "    {} {{ {} }},", v.name, fields.join(", "));
                        }
                    }
                }
                let _ = writeln!(out, "}}");
                render_methods(&mut out, reg, id, &e.name);
            }
            _ => {}
        }
    }

    for module in reg.modules() {
        out.push('\n');
        if let Some(doc) = &module.doc {
            for line in doc.lines() {
                let _ = writeln!(out, "/// {line}");
            }
        }
        let _ = writeln!(out, "mod {} {{", module.name);
        for (name, ty, value) in &module.consts {
            let _ = writeln!(
                out,
                "    const {name}: {} = {}",
                ty.display(&reg.defs),
                const_expr(value)
            );
        }
        for f in &module.fns {
            if let Some(doc) = &f.doc {
                for line in doc.lines() {
                    let _ = writeln!(out, "    /// {line}");
                }
            }
            let _ = writeln!(
                out,
                "    fn {}({}){}",
                f.name,
                sig_params(&f.sig, f.param_names(), reg, false),
                ret_suffix(&f.sig.ret, reg)
            );
        }
        let _ = writeln!(out, "}}");
    }
    out
}

/// Methods (PRD §6.2) render as an impl block of bodyless fns.
fn render_methods(out: &mut String, reg: &Registry, id: DefId, ty_name: &str) {
    let methods = reg.methods_of(id);
    if methods.is_empty() {
        return;
    }
    let _ = writeln!(out, "\nimpl {ty_name} {{");
    for m in methods {
        if let Some(doc) = &m.doc {
            for line in doc.lines() {
                let _ = writeln!(out, "    /// {line}");
            }
        }
        let _ = writeln!(
            out,
            "    fn {}({}){}",
            m.name,
            sig_params(&m.sig, m.param_names(), reg, true),
            ret_suffix(&m.sig.ret, reg)
        );
    }
    let _ = writeln!(out, "}}");
}

/// Render a parameter list. Declared names are emitted as written; where
/// the host declared none the positional placeholder stands in, because
/// the grammar requires a name and inventing a plausible one would hide
/// that nothing was ever declared.
fn sig_params(sig: &FnSig, names: Option<&[String]>, reg: &Registry, method: bool) -> String {
    let mut parts: Vec<String> = Vec::new();
    if method {
        parts.push("self".into());
    }
    for (i, p) in sig.params.iter().enumerate() {
        let name = names
            .and_then(|names| names.get(i))
            .cloned()
            .unwrap_or_else(|| positional_param_name(i));
        parts.push(format!("{name}: {}", p.display(&reg.defs)));
    }
    parts.join(", ")
}

fn ret_suffix(ret: &Type, reg: &Registry) -> String {
    if *ret == Type::Unit {
        String::new()
    } else {
        format!(" -> {}", ret.display(&reg.defs))
    }
}

/// A registered constant as source text that [`eval_const`] reads back to
/// the identical value.
///
/// Three of these have no literal spelling — `int`'s most negative value
/// (its magnitude does not fit in `int`) and the non-finite floats — hence
/// the arithmetic. Rust writes `i64::MIN` the same way, and for the same
/// reason.
fn const_expr(c: &Const) -> String {
    match c {
        Const::Int(i64::MIN) => format!("{} - 1", i64::MIN + 1),
        Const::Int(n) => n.to_string(),
        Const::Float(f) if f.is_nan() => "0.0 / 0.0".into(),
        Const::Float(f) if *f == f64::INFINITY => "1.0 / 0.0".into(),
        Const::Float(f) if *f == f64::NEG_INFINITY => "-1.0 / 0.0".into(),
        // `{:?}` is f64's shortest round-tripping form, and always carries
        // a `.` or an exponent, so it lexes back as a float and not an int.
        Const::Float(f) => format!("{f:?}"),
        Const::Bool(b) => b.to_string(),
        Const::Char(c) => format!("'{}'", c.escape_debug()),
        Const::Str(s) => format!("\"{}\"", s.chars().map(escape_in_str).collect::<String>()),
        Const::Unit => "()".into(),
    }
}

/// One character of a string literal. Rust's `escape_debug` covers the
/// backslash escapes the lexer understands; braces are the addition,
/// because in a *string* they open an interpolation hole and the doubled
/// form is how the lexer is told to read a literal one. A char literal
/// holds exactly one character, so the same doubling there would produce
/// `'{{'`, which does not lex.
fn escape_in_str(c: char) -> String {
    match c {
        '{' => "{{".into(),
        '}' => "}}".into(),
        _ => c.escape_debug().to_string(),
    }
}

// ------------------------------------------------------------------ load

/// Source location of a declaration inside a `.wscripti` file — the LSP's
/// goto-definition target for host symbols (PRD §9, feature 3).
#[derive(Debug, Clone, Default)]
pub struct WscriptiIndex {
    /// `module::fn` and `module::const` → span.
    pub module_items: HashMap<(String, String), Span>,
    /// type name → span; (type, method) → span.
    pub types: HashMap<String, Span>,
    pub methods: HashMap<(String, String), Span>,
}

struct StubFn {
    name: String,
}

impl HostCallable for StubFn {
    fn call(&self, _ctx: &mut dyn HostCtx, _args: Vec<Value>) -> Result<Value, HostError> {
        Err(HostError::msg(format!(
            "`{}` comes from a .wscripti interface file and has no implementation \
             (interfaces are for checking, not running)",
            self.name
        )))
    }
}

/// Load one interface file's declarations into `reg`. Declarations whose
/// names already exist are skipped (the live registration wins — e.g. the
/// CLI registers the real stdlib and also reads std.wscripti via wscript.toml).
/// Returns diagnostics (parse errors and unsupported forms) and the
/// definition index for the LSP.
pub fn load(source: &str, reg: &mut Registry) -> (Vec<Diagnostic>, WscriptiIndex) {
    let parsed = crate::parse(source);
    let mut diags = parsed.diags;
    let mut index = WscriptiIndex::default();
    let mut loader = Loader {
        reg,
        diags: &mut diags,
        index: &mut index,
    };
    // Types first (signatures reference them), then modules.
    for item in &parsed.file.items {
        loader.load_type(item);
    }
    for item in &parsed.file.items {
        match item {
            Item::Mod(m) => loader.load_module(m),
            Item::Impl(im) => loader.load_impl(im),
            // Unit families are a script-level construct: at the host
            // boundary their values are just the backing number.
            Item::Units(u) => {
                let span = u.name.span;
                loader.unregistrable(
                    span,
                    "`units` declarations are not allowed in an interface file",
                );
            }
            _ => {}
        }
    }
    (diags, index)
}

struct Loader<'a> {
    reg: &'a mut Registry,
    diags: &'a mut Vec<Diagnostic>,
    index: &'a mut WscriptiIndex,
}

impl<'a> Loader<'a> {
    fn error(&mut self, span: Span, msg: impl Into<String>, help: impl Into<String>) {
        self.diags
            .push(Diagnostic::error("E0271", span, msg).with_help(help));
    }

    /// The default `E0271` help: nothing more specific to say than that
    /// this declaration did not make it into the registry.
    fn unregistrable(&mut self, span: Span, msg: impl Into<String>) {
        self.error(
            span,
            msg,
            "this declaration in the .wscripti interface file could not be registered",
        );
    }

    fn name_taken(&self, name: &str) -> bool {
        self.reg.defs.id_of(name).is_some()
    }

    fn load_type(&mut self, item: &Item) {
        match item {
            Item::Struct(s) => {
                self.index.types.insert(s.name.name.clone(), s.name.span);
                if self.name_taken(&s.name.name) {
                    return;
                }
                let id = self.reg.defs.push(DefKind::Struct(StructDef {
                    name: s.name.name.clone(),
                    fields: vec![],
                    opaque: s.opaque,
                    host: true,
                    rust_type: None,
                }));
                let fields: Vec<(String, Type)> = s
                    .fields
                    .iter()
                    .map(|f| (f.name.name.clone(), self.resolve_type(&f.ty)))
                    .collect();
                if let DefKind::Struct(sd) = &mut self.reg.defs.defs[id.index()] {
                    sd.fields = fields;
                }
            }
            Item::Enum(e) => {
                self.index.types.insert(e.name.name.clone(), e.name.span);
                if self.name_taken(&e.name.name) {
                    return;
                }
                let id = self.reg.defs.push(DefKind::Enum(EnumDef {
                    name: e.name.name.clone(),
                    variants: vec![],
                    host: true,
                    rust_type: None,
                }));
                let variants: Vec<VariantDef> = e
                    .variants
                    .iter()
                    .map(|v| {
                        let (kind, fields) = match &v.body {
                            VariantBody::Unit => (VariantKind::Unit, vec![]),
                            VariantBody::Tuple(tys) => (
                                VariantKind::Tuple,
                                tys.iter()
                                    .enumerate()
                                    .map(|(i, t)| (i.to_string(), self.resolve_type(t)))
                                    .collect(),
                            ),
                            VariantBody::Struct(fs) => (
                                VariantKind::Struct,
                                fs.iter()
                                    .map(|f| (f.name.name.clone(), self.resolve_type(&f.ty)))
                                    .collect(),
                            ),
                        };
                        VariantDef {
                            name: v.name.name.clone(),
                            kind,
                            fields,
                        }
                    })
                    .collect();
                if let DefKind::Enum(ed) = &mut self.reg.defs.defs[id.index()] {
                    ed.variants = variants;
                }
            }
            _ => {}
        }
    }

    fn load_module(&mut self, m: &ModDecl) {
        if self.reg.modules().iter().any(|x| x.name == m.name.name) {
            // Live registration wins; still index for goto-definition.
            for item in &m.items {
                if let Item::Fn(f) = item {
                    self.index
                        .module_items
                        .insert((m.name.name.clone(), f.name.name.clone()), f.name.span);
                } else if let Item::Const(c) = item {
                    self.index
                        .module_items
                        .insert((m.name.name.clone(), c.name.name.clone()), c.name.span);
                }
            }
            return;
        }
        let mut def = ModuleDef {
            name: m.name.name.clone(),
            fns: Vec::new(),
            consts: Vec::new(),
            types: Vec::new(),
            doc: m.doc.clone(),
        };
        for item in &m.items {
            match item {
                Item::Fn(f) => {
                    if !f.type_params.is_empty() {
                        self.diags.push(
                            Diagnostic::error(
                                "E0254",
                                f.name.span,
                                "generic host functions are not supported",
                            )
                            .with_help(
                                "host functions are monomorphic Rust closures; declare \
                                 concrete overloads instead",
                            ),
                        );
                        continue;
                    }
                    self.index
                        .module_items
                        .insert((m.name.name.clone(), f.name.name.clone()), f.name.span);
                    let sig = self.fn_sig(f);
                    let idx = self.reg.push_host_fn(HostFnEntry {
                        sig: sig.clone(),
                        imp: Arc::new(StubFn {
                            name: format!("{}::{}", m.name.name, f.name.name),
                        }),
                    });
                    def.fns.push(HostFnDecl {
                        name: f.name.name.clone(),
                        sig,
                        host_idx: idx,
                        doc: f.doc.clone(),
                        params: param_names(f),
                    });
                }
                Item::Const(c) => {
                    self.index
                        .module_items
                        .insert((m.name.name.clone(), c.name.name.clone()), c.name.span);
                    let ty = self.resolve_type(&c.ty);
                    let value = self.const_value(c, &ty);
                    def.consts.push((c.name.name.clone(), ty, value));
                }
                other => {
                    let span = item_span(other);
                    self.unregistrable(span, "only fn and const declarations belong in mod blocks");
                }
            }
        }
        self.reg.push_module(def);
    }

    fn load_impl(&mut self, im: &ImplDecl) {
        if im.trait_name.is_some() {
            self.unregistrable(im.span, "trait impls do not appear in interface files");
            return;
        }
        let Some(def_id) = self.find_type(&im.ty_name.name) else {
            self.unregistrable(
                im.ty_name.span,
                format!("unknown type `{}` in interface impl", im.ty_name.name),
            );
            return;
        };
        let already = !self.reg.methods_of(def_id).is_empty();
        for f in &im.fns {
            self.index
                .methods
                .insert((im.ty_name.name.clone(), f.name.name.clone()), f.name.span);
            if already {
                continue; // live registration wins
            }
            // Drop the `self` receiver from the registered signature.
            let params: Vec<Type> = f
                .params
                .iter()
                .filter(|p| !p.is_self)
                .map(|p| match &p.ty {
                    Some(t) => self.resolve_type(t),
                    None => Type::Error,
                })
                .collect();
            let ret = f
                .ret
                .as_ref()
                .map(|t| self.resolve_type(t))
                .unwrap_or(Type::Unit);
            let sig = FnSig::new(params, ret);
            let idx = self.reg.push_host_fn(HostFnEntry {
                sig: sig.clone(),
                imp: Arc::new(StubFn {
                    name: format!("{}::{}", im.ty_name.name, f.name.name),
                }),
            });
            self.reg.push_method(
                def_id,
                HostFnDecl {
                    name: f.name.name.clone(),
                    sig,
                    host_idx: idx,
                    doc: f.doc.clone(),
                    params: param_names(f),
                },
            );
        }
    }

    /// The struct or enum called `name` — the only kinds an `impl` block
    /// in an interface can attach methods to.
    fn find_type(&self, name: &str) -> Option<DefId> {
        let id = self.type_named(name)?;
        matches!(self.reg.defs.get(id), DefKind::Struct(_) | DefKind::Enum(_)).then_some(id)
    }

    fn fn_sig(&mut self, f: &FnDecl) -> FnSig {
        let params: Vec<Type> = f
            .params
            .iter()
            .filter(|p| !p.is_self)
            .map(|p| match &p.ty {
                Some(t) => self.resolve_type(t),
                None => Type::Error,
            })
            .collect();
        let ret = f
            .ret
            .as_ref()
            .map(|t| self.resolve_type(t))
            .unwrap_or(Type::Unit);
        FnSig::new(params, ret)
    }

    /// The checker's own `TypeExpr → Type` lowering, so a declaration an
    /// interface makes is one a script could have made.
    ///
    /// Well-formed is not the same as registrable, and `dyn` is where the
    /// two part: it is a perfectly good script type, but a host trait to
    /// dispatch through is v2 (PRD §6.2). No interface reaches this today
    /// — an interface file cannot declare a trait, and every trait a host
    /// registry can see is a builtin *operator* trait, which the resolver
    /// rejects for `dyn` itself. It is here because the alternative to a
    /// diagnostic is a `Type::Dyn` sitting silently in a host signature,
    /// and the loader is where "may not be registered" is decided.
    fn resolve_type(&mut self, t: &TypeExpr) -> Type {
        let ty = resolve::resolve_type(self, t);
        if has_dyn(&ty) {
            self.unregistrable(
                t.span,
                "`dyn` types do not appear in interface files (host traits are v2)",
            );
            return Type::Error;
        }
        ty
    }

    /// The value of an interface constant. A constant is the one thing in
    /// an interface file that is not merely a signature: `wscript check`
    /// folds it into the script, so a wrong one is a silent behaviour
    /// difference between `check` and `run`, and a missing one has no
    /// defensible stand-in.
    fn const_value(&mut self, c: &ConstDecl, ty: &Type) -> Const {
        let Some(value) = &c.value else {
            self.error(
                c.span,
                format!("constant `{}` has no value", c.name.name),
                "an interface constant is folded into scripts that read it, so it \
                 must say what it is: `const NAME: int = 16`",
            );
            return rejected_placeholder(ty);
        };
        match self.eval_const(value, ty) {
            Some(folded) => folded,
            None => {
                let name = &c.name.name;
                let shown = ty.display(&self.reg.defs);
                self.error(
                    value.span,
                    format!("`{name}` is not a constant `{shown}`"),
                    "an interface constant is a literal of its declared type, or — \
                     for the numbers with no literal spelling — a constant \
                     expression over numeric literals and `+ - * /`",
                );
                rejected_placeholder(ty)
            }
        }
    }

    /// Const-evaluate a constant's value at its declared type, or `None`
    /// if the expression is not one.
    fn eval_const(&mut self, e: &Expr, ty: &Type) -> Option<Const> {
        match (ty, &e.kind) {
            (Type::Int, _) => match eval_num(e)? {
                Num::Int(n) => Some(Const::Int(n)),
                Num::Float(_) => None,
            },
            (Type::Float, _) => match eval_num(e)? {
                Num::Float(f) => Some(Const::Float(f)),
                Num::Int(_) => None,
            },
            (Type::Bool, ExprKind::BoolLit(b)) => Some(Const::Bool(*b)),
            (Type::Char, ExprKind::CharLit(c)) => Some(Const::Char(*c)),
            (Type::Str, ExprKind::StrLit(s)) => Some(Const::Str(Arc::from(s.as_str()))),
            (Type::Unit, ExprKind::UnitLit) => Some(Const::Unit),
            _ => None,
        }
    }
}

/// `dyn` anywhere in a type, however deeply nested — `List[dyn Display]`
/// smuggles one in just as surely as a bare `dyn Display` does.
fn has_dyn(t: &Type) -> bool {
    match t {
        Type::Dyn(_) => true,
        Type::List(e) | Type::Option(e) | Type::Weak(e) => has_dyn(e),
        Type::Map(k, v) | Type::Result(k, v) => has_dyn(k) || has_dyn(v),
        Type::Fn(sig) => sig.params.iter().any(has_dyn) || has_dyn(&sig.ret),
        _ => false,
    }
}

/// What a rejected constant is registered as, so the rest of the file
/// keeps checking against something of the right type. It is not a value
/// anyone should read: the diagnostic that precedes it is the outcome.
fn rejected_placeholder(ty: &Type) -> Const {
    match ty {
        Type::Int => Const::Int(0),
        Type::Float => Const::Float(0.0),
        Type::Bool => Const::Bool(false),
        Type::Char => Const::Char('\0'),
        Type::Str => Const::Str(Arc::from("")),
        _ => Const::Unit,
    }
}

#[derive(Clone, Copy)]
enum Num {
    Int(i64),
    Float(f64),
}

/// A constant expression over numeric literals: the same grammar unit
/// conversion factors use (E0268). Plain literals would very nearly do,
/// but three values a host can legitimately register cannot be written as
/// one — `int`'s most negative value, and ±infinity and NaN.
fn eval_num(e: &Expr) -> Option<Num> {
    match &e.kind {
        ExprKind::IntLit(n) => Some(Num::Int(*n)),
        ExprKind::FloatLit(f) => Some(Num::Float(*f)),
        ExprKind::Unary {
            op: UnOp::Neg,
            expr,
        } => match eval_num(expr)? {
            Num::Int(n) => n.checked_neg().map(Num::Int),
            Num::Float(f) => Some(Num::Float(-f)),
        },
        ExprKind::Binary { op, lhs, rhs } => {
            let op = match op {
                BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div => *op,
                _ => return None,
            };
            match (eval_num(lhs)?, eval_num(rhs)?) {
                // Integer arithmetic is checked: an interface that
                // overflows is describing a value `int` cannot hold.
                (Num::Int(a), Num::Int(b)) => match op {
                    BinOp::Add => a.checked_add(b),
                    BinOp::Sub => a.checked_sub(b),
                    BinOp::Mul => a.checked_mul(b),
                    _ => a.checked_div(b),
                }
                .map(Num::Int),
                // Float division by zero is how ±inf and NaN are spelled,
                // so it is deliberately not an error here.
                (Num::Float(a), Num::Float(b)) => Some(Num::Float(match op {
                    BinOp::Add => a + b,
                    BinOp::Sub => a - b,
                    BinOp::Mul => a * b,
                    _ => a / b,
                })),
                // wscript has no implicit numeric widening; neither has this.
                _ => None,
            }
        }
        _ => None,
    }
}

impl TypeScope for Loader<'_> {
    fn type_named(&self, name: &str) -> Option<DefId> {
        self.reg.defs.id_of(name)
    }

    fn defs(&self) -> &DefTable {
        &self.reg.defs
    }

    fn report(&mut self, d: Diagnostic) {
        self.diags.push(d);
    }
}

/// Parameter names declared by an interface `fn`, receiver excluded.
///
/// The interface grammar requires a name for every parameter, so the
/// emitter writes positional placeholders (`a0`, `a1`, …) wherever the host
/// declared none. Loading those back as declared names would launder a
/// placeholder into a fact, so a parameter list that is entirely
/// placeholders loads as undeclared — exactly what it was before it was
/// written out.
fn param_names(f: &FnDecl) -> Vec<String> {
    let names: Vec<String> = f
        .params
        .iter()
        .filter(|p| !p.is_self)
        .map(|p| p.name.name.clone())
        .collect();
    if names
        .iter()
        .enumerate()
        .all(|(i, n)| *n == positional_param_name(i))
    {
        return Vec::new();
    }
    names
}

fn item_span(item: &Item) -> Span {
    match item {
        Item::Use(u) => u.span,
        Item::Fn(f) => f.span,
        Item::Struct(s) => s.span,
        Item::Enum(e) => e.span,
        Item::Trait(t) => t.span,
        Item::Impl(i) => i.span,
        Item::Mod(m) => m.span,
        Item::Const(c) => c.span,
        Item::Units(u) => u.span,
    }
}
